      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n인체바이오모니터링 기반 유해물질 노출평가 참여자 모집\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.16. 20:00\n조회 107\n구독\n인체바이오모니터링 기반 유해물질 노출평가 참여자 모집\n이 조사는 경희대에서 7월부터 진행을 하고 있습니다.\n참여하신분 &\n신청하신분은 재신청 안하셔도 됩니다\n대상\n임신 중이시거나 생후 12개월 이상 만 6세 이하 자녀를 키우고 계신 분이라면 참여하실 수 있고요,\n연구는 전국 주요 거점에서 특정 날짜와 시간에 맞춰 진행되는 방식으로,\n가까운 거점으로 한 번만 방문해 주시면 됩니다.\n방문 전 설문지와 소변 채취 도구를 택배로 미리 보내드리니,\n작성 및 채취 후 현장에 가져오시면 됩니다.\n현장에서는 신체계측, 혈압 측정, 채혈(임산부만) 등이 함께 진행됩니다.\n현장 소요 시간은 약 1시간 정도입니다.\n사례비-영유아 6만원 임산부6만원\n오시기전 준비물\n동봉된 설문지/배뇨통\n보내주실때\n1.엄마성함\n2.연락처\n3.생년월일\n4.현재 임신여부\n5.자녀 개월수\n6.참여 가능한 요일(10월중)\nhttps://forms.gle/HfNQoApMofnr3eEBA\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.16. 20:01 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n총소요시간 2시간 15만원) 9월 28일~0월 4일 까지) 5세미만 유자녀 20대 엄마) 돌봄 관련 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.16.\n댓글\n0\n인체바이오모니터링 기반 유해물질 노출평가 참여자 모집\n좌담회알바좌담회카페\n26.09.16.\n댓글\n1\n10/12일~14일) 20세~60세 남,녀) GLP-1 복용자 입마름 증상 관련 모집\n좌담회알바좌담회카페\n26.09.16.\n댓글\n1\n9/30(수)~10/1)만 30~59세 남녀) 청소기 관련 좌담회\n좌담회알바좌담회카페\n26.09.16.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
