      "raw_content": "상황별 고급차 차량 이용 패턴 인터뷰2-고급차 보유자 10/14 이후[20만원]\n​\n대상 : 아래 모집내용 5~7 중 해당 조건을 충족하는 차량 보유자\n자동차 등록증 제출 가능한 분\n일정 : 10월 14일 이후 원하시는 날짜,시간대로 조율 가능\n방법 : 1:1 인터뷰\n소요시간 : 2시간 내외\n사례비 : 20만원(현장에서 바로 지급/신분증 지참)\n​\n모집내용 5\n조건: 곡선,경사,합류,추월 등 평지,직선 도로보다 운전이 어려운 도로에서 코너링,핸들링,기어 등 직접 조작해 운전하는 재미를 즐기시는 분\n(최근 1년 내 2번 이상 환경이 다른 운전이 어려운 도로,드라이빙 프로그램 등에서 수동변속 등을 이용해 주행 경험 있으신 분)\n차종: BMW : M2 / M3 / M4 / M5 / M8 / XM\nX3M 대회 / X4M 대회 / X5M 대회 / X6M 대회\n메르세데스-AMG : AMG A 45 S / AMG E 53\nAMG CLA 45 S / AMG GLC 43 / AMG GT\nAMG GLE 63 S / AMG 63 SE 퍼포먼스\n제네시스 : GV60 마그마\n​\n모집내용 6\n조건: FSD(감독형) 운전 비율 50%이상 사용자(대시보드 FSD 주행비율 사진 제출 가능하신 분)\n차종: 2023년식 이상 테슬라 모델 S, 테슬라 모델 X\n​\n모집내용 7\n조건: 차량 관련 정보,소식에 관심이 많고 직접 참여하거나 적극적으로 정보를 찾아보고 게시하는 등 활발하게 참여 및 활동 하시는 분\n(SNS,자동차 관련 커뮤니티 등에 리뷰,주행 등 차량 관련 컨텐츠(사진,영상,게시글 등)를 월 1회 이상 작성하시거나\n자동차 동호회,커뮤니티 오프라인 모임,시승 행사 등 차량 관련 모임,행사에 최근 6개월 내 최소 월 1회 이상 참여하시는 분)\n차종: 2023년식 이상 제네시스,BMW,Mercedes-Benz 보유자\n​\n신청하기",
